package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Original API67 source, metadata and assertions admitted on Salesforce in Wave59.
func TestRunJSONExplicitPrettyContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeExplicitPretty67.cls"), "@IsTest private class GladeExplicitPretty67 {\nprivate static void finish(List<Object> rows,Integer expected,String caseName){System.assertEquals(expected,rows.size(),'All discriminator operations retained');String text=JSON.serialize(rows);System.assert(text.length()<2900,'Observation exceeds transport bound');System.assertEquals(expectedRows(caseName),rows,'Exact source-bound Salesforce rows and keysets');}\nprivate static Map<String,Object> phase(String p){return new Map<String,Object>{'phase'=>p};}\nprivate static void failure(Map<String,Object> row,Exception e){row.put('type',e.getTypeName());row.put('message',e.getMessage());}\n@IsTest static void object(){List<Object> rows=new List<Object>();JSONGenerator g=JSON.createGenerator(true);Map<String,Object> row=phase('build');try{g.writeStartObject();g.writeStringField('name','owned');row.put('returned',true);}catch(Exception e){failure(row,e);}rows.add(row);row=phase('explicitEnd');try{g.writeEndObject();row.put('returned',true);}catch(Exception e){failure(row,e);}rows.add(row);row=phase('closedAfterEnd');try{row.put('value',g.isClosed());}catch(Exception e){failure(row,e);}rows.add(row);row=phase('getAsString');try{row.put('value',g.getAsString());}catch(Exception e){failure(row,e);}rows.add(row);row=phase('closedAfterRead');try{row.put('value',g.isClosed());}catch(Exception e){failure(row,e);}rows.add(row);finish(rows,5,'object');}\n@IsTest static void array(){List<Object> rows=new List<Object>();JSONGenerator g=JSON.createGenerator(true);Map<String,Object> row=phase('build');try{g.writeStartArray();g.writeNumber(7);g.writeBoolean(true);row.put('returned',true);}catch(Exception e){failure(row,e);}rows.add(row);row=phase('explicitEnd');try{g.writeEndArray();row.put('returned',true);}catch(Exception e){failure(row,e);}rows.add(row);row=phase('closedAfterEnd');try{row.put('value',g.isClosed());}catch(Exception e){failure(row,e);}rows.add(row);row=phase('getAsString');try{row.put('value',g.getAsString());}catch(Exception e){failure(row,e);}rows.add(row);row=phase('closedAfterRead');try{row.put('value',g.isClosed());}catch(Exception e){failure(row,e);}rows.add(row);finish(rows,5,'array');}\n@IsTest static void nestedObject(){List<Object> rows=new List<Object>();JSONGenerator g=JSON.createGenerator(true);Map<String,Object> row=phase('build');try{g.writeStartObject();g.writeFieldName('items');g.writeStartArray();g.writeStartObject();g.writeStringField('name','owned');row.put('returned',true);}catch(Exception e){failure(row,e);}rows.add(row);row=phase('explicitEnd');try{g.writeEndObject();g.writeEndArray();g.writeEndObject();row.put('returned',true);}catch(Exception e){failure(row,e);}rows.add(row);row=phase('closedAfterEnd');try{row.put('value',g.isClosed());}catch(Exception e){failure(row,e);}rows.add(row);row=phase('getAsString');try{row.put('value',g.getAsString());}catch(Exception e){failure(row,e);}rows.add(row);row=phase('closedAfterRead');try{row.put('value',g.isClosed());}catch(Exception e){failure(row,e);}rows.add(row);finish(rows,5,'nestedObject');}\n@IsTest static void nestedArray(){List<Object> rows=new List<Object>();JSONGenerator g=JSON.createGenerator(true);Map<String,Object> row=phase('build');try{g.writeStartArray();g.writeStartArray();g.writeNumber(7);row.put('returned',true);}catch(Exception e){failure(row,e);}rows.add(row);row=phase('explicitEnd');try{g.writeEndArray();g.writeEndArray();row.put('returned',true);}catch(Exception e){failure(row,e);}rows.add(row);row=phase('closedAfterEnd');try{row.put('value',g.isClosed());}catch(Exception e){failure(row,e);}rows.add(row);row=phase('getAsString');try{row.put('value',g.getAsString());}catch(Exception e){failure(row,e);}rows.add(row);row=phase('closedAfterRead');try{row.put('value',g.isClosed());}catch(Exception e){failure(row,e);}rows.add(row);finish(rows,5,'nestedArray');}\n@IsTest static void emptyObject(){List<Object> rows=new List<Object>();JSONGenerator g=JSON.createGenerator(true);Map<String,Object> row=phase('build');try{g.writeStartObject();row.put('returned',true);}catch(Exception e){failure(row,e);}rows.add(row);row=phase('explicitEnd');try{g.writeEndObject();row.put('returned',true);}catch(Exception e){failure(row,e);}rows.add(row);row=phase('closedAfterEnd');try{row.put('value',g.isClosed());}catch(Exception e){failure(row,e);}rows.add(row);row=phase('getAsString');try{row.put('value',g.getAsString());}catch(Exception e){failure(row,e);}rows.add(row);row=phase('closedAfterRead');try{row.put('value',g.isClosed());}catch(Exception e){failure(row,e);}rows.add(row);finish(rows,5,'emptyObject');}\n@IsTest static void emptyArray(){List<Object> rows=new List<Object>();JSONGenerator g=JSON.createGenerator(true);Map<String,Object> row=phase('build');try{g.writeStartArray();row.put('returned',true);}catch(Exception e){failure(row,e);}rows.add(row);row=phase('explicitEnd');try{g.writeEndArray();row.put('returned',true);}catch(Exception e){failure(row,e);}rows.add(row);row=phase('closedAfterEnd');try{row.put('value',g.isClosed());}catch(Exception e){failure(row,e);}rows.add(row);row=phase('getAsString');try{row.put('value',g.getAsString());}catch(Exception e){failure(row,e);}rows.add(row);row=phase('closedAfterRead');try{row.put('value',g.isClosed());}catch(Exception e){failure(row,e);}rows.add(row);finish(rows,5,'emptyArray');}\nprivate static List<Object> expectedRows(String caseName){\nif(caseName=='object'){return new List<Object>{new Map<String,Object>{'returned'=>true,'phase'=>'build'},new Map<String,Object>{'returned'=>true,'phase'=>'explicitEnd'},new Map<String,Object>{'value'=>false,'phase'=>'closedAfterEnd'},new Map<String,Object>{'value'=>'{\\n  \"name\" : \"owned\"\\n}','phase'=>'getAsString'},new Map<String,Object>{'value'=>true,'phase'=>'closedAfterRead'}};}\nif(caseName=='array'){return new List<Object>{new Map<String,Object>{'returned'=>true,'phase'=>'build'},new Map<String,Object>{'returned'=>true,'phase'=>'explicitEnd'},new Map<String,Object>{'value'=>false,'phase'=>'closedAfterEnd'},new Map<String,Object>{'value'=>'[ 7, true ]','phase'=>'getAsString'},new Map<String,Object>{'value'=>true,'phase'=>'closedAfterRead'}};}\nif(caseName=='nestedObject'){return new List<Object>{new Map<String,Object>{'returned'=>true,'phase'=>'build'},new Map<String,Object>{'returned'=>true,'phase'=>'explicitEnd'},new Map<String,Object>{'value'=>false,'phase'=>'closedAfterEnd'},new Map<String,Object>{'value'=>'{\\n  \"items\" : [ {\\n    \"name\" : \"owned\"\\n  } ]\\n}','phase'=>'getAsString'},new Map<String,Object>{'value'=>true,'phase'=>'closedAfterRead'}};}\nif(caseName=='nestedArray'){return new List<Object>{new Map<String,Object>{'returned'=>true,'phase'=>'build'},new Map<String,Object>{'returned'=>true,'phase'=>'explicitEnd'},new Map<String,Object>{'value'=>false,'phase'=>'closedAfterEnd'},new Map<String,Object>{'value'=>'[ [ 7 ] ]','phase'=>'getAsString'},new Map<String,Object>{'value'=>true,'phase'=>'closedAfterRead'}};}\nif(caseName=='emptyObject'){return new List<Object>{new Map<String,Object>{'returned'=>true,'phase'=>'build'},new Map<String,Object>{'returned'=>true,'phase'=>'explicitEnd'},new Map<String,Object>{'value'=>false,'phase'=>'closedAfterEnd'},new Map<String,Object>{'value'=>'{ }','phase'=>'getAsString'},new Map<String,Object>{'value'=>true,'phase'=>'closedAfterRead'}};}\nif(caseName=='emptyArray'){return new List<Object>{new Map<String,Object>{'returned'=>true,'phase'=>'build'},new Map<String,Object>{'returned'=>true,'phase'=>'explicitEnd'},new Map<String,Object>{'value'=>false,'phase'=>'closedAfterEnd'},new Map<String,Object>{'value'=>'[ ]','phase'=>'getAsString'},new Map<String,Object>{'value'=>true,'phase'=>'closedAfterRead'}};}\nSystem.assert(false,'Unknown exact case');return null;\n}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeExplicitPretty67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}], \"sourceApiVersion\": \"67.0\"}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 6 || got.Passed != 6 || got.Failed != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("Exact discriminator contracts: %s", data)
	}
}
